```rust
pub fn trap(height: &[u32]) -> u64 {
    if height.len() < 3 {
        return 0;
    }

    let mut left = 0;
    let mut right = height.len() - 1;
    let mut left_max = height[left];
    let mut right_max = height[right];
    let mut total = 0u64;

    while left < right {
        if left_max <= right_max {
            left += 1;
            left_max = left_max.max(height[left]);
            total += (left_max - height[left]) as u64;
        } else {
            right -= 1;
            right_max = right_max.max(height[right]);
            total += (right_max - height[right]) as u64;
        }
    }

    total
}
```

