pub fn sum_checked(values: &[i64]) -> Result<i64, &'static str> {
    if values.is_empty() {
        return Err("empty");
    }
    let mut total: i64 = 0;
    for value in values {
        total = match total.checked_add(*value) {
            Some(sum) => sum,
            None => return Err("overflow"),
        };
    }
    Ok(total)
}
